  const userId = ctx.userId ?? ctx.fromUserId ?? ctx.from?.id;
  const agentId = ctx.agentId ?? '';
  const text = ctx.textContent ?? ctx.content ?? '';

  // 只在頂級特助分工群 + 三隻機之一 + 教練發的訊息 + 有內容
  if (chatId !== TARGET_GROUP_CHAT_ID) return;
  if (!ALL_AGENTS.includes(agentId)) return;
  if (Number(userId) !== COACH_USER_ID) return;
  if (!text || text.trim().length < 5) return;

  // 60 秒內同訊息不重複處理（每隻機獨立 cooldown，以 agentId 區隔）
  if (isInCooldown(`${agentId}:${text}`)) return;

  try {
    let injection = null;

    if (agentId === MAIN_AGENT_ID) {
      // 學長：生議程注入
      const agenda = await generateAgenda(text);
      if (!agenda) return;
      injection = buildLeaderInjection(agenda);
    } else if (FOLLOWER_AGENT_IDS.includes(agentId)) {
      // 學弟學妹：注入硬性等待指令（不呼叫 LLM，省 token）
      injection = buildFollowerInjection(agentId);
    }

    if (!injection) return;
    if (!event.context.inject) event.context.inject = [];
    event.context.inject.push(injection);
  } catch (err) {
    // 靜默失敗，不影響訊息流轉
  }
};

module.exports = handler;
module.exports.default = handler;

